// GET has an empty body, so the signature covers `${timestamp}.`
const crypto = require('crypto');
const secret = $env.N8N_TO_CONVEX_SECRET;
if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set');
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.`).digest('hex');
return [{ json: { timestamp, signature } }];

// Mock delivery: logs instead of emailing. Swap for Send Email / Slack / Discord
// with an n8n credential. A failed send is reported back as status "failed".
const loan = $json;
try {
  const message = {
    to: loan.borrower.email,
    subject: `Reminder: please return the ${loan.toolName}`,
    text: `Hi ${loan.borrower.name}, the ${loan.toolName} was due back on ${loan.dueDate} (${loan.daysOverdue} day${loan.daysOverdue === 1 ? '' : 's'} ago). Please return it or message the owner.`,
  };
  console.log('[LendLoop reminder]', JSON.stringify(message));
  return { json: { loanId: loan.loanId, reminderKey: loan.reminderKey, status: 'sent', detail: 'Reminder sent (mock)' } };
} catch (error) {
  return { json: { loanId: loan.loanId, reminderKey: loan.reminderKey, status: 'failed', detail: String(error.message).slice(0, 200) } };
}

// Sign the exact string we send, so Convex verifies the bytes it receives.
const crypto = require('crypto');
const secret = $env.N8N_TO_CONVEX_SECRET;
const body = JSON.stringify({ loanId: $json.loanId, reminderKey: $json.reminderKey, status: $json.status, detail: $json.detail });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
return { json: { body, timestamp, signature } };
